    fun search(query: String): List<PayrollCodeReference> {
        val terms = query.trim().lowercase().split(Regex("\\s+")).filter(String::isNotBlank)
        if (terms.isEmpty()) return entries

        return entries.filter { entry ->
            val searchableText = buildString {
                append(entry.code)
                append(' ')
                append(entry.shortName)
                append(' ')
                append(entry.description)
                append(' ')
                append(if (entry.type == PayrollPaymentType.ACCRUAL) "начисление начисления" else "удержание удержания")
            }.lowercase()
            val normalizedCode = normalizeCodeLookalikes(entry.code)
            terms.all { term ->
                searchableText.contains(term) ||
                    (term.any(Char::isDigit) && normalizedCode.contains(normalizeCodeLookalikes(term)))
            }
        }
    }

    private fun normalizeCodeLookalikes(value: String): String = buildString(value.length) {
        value.lowercase().forEach { character ->
            append(
                when (character) {
                    'а' -> 'a'
                    'в' -> 'b'
                    'е' -> 'e'
                    'к' -> 'k'
                    'м' -> 'm'
                    'н' -> 'h'
                    'о' -> 'o'
                    'р' -> 'p'
                    'с' -> 'c'
                    'т' -> 't'
                    'у' -> 'y'
                    'х' -> 'x'
                    else -> character
                }
            )
        }
    }

    private fun numericCodePart(code: String): Int =
        code.takeWhile(Char::isDigit).toIntOrNull() ?: Int.MAX_VALUE
}
